import{_ as o,o as a,c as r,a3 as t}from"./chunks/framework.BFeCKmyl.js";const u=JSON.parse('{"title":"Contato","description":"","frontmatter":{"title":"Contato"},"headers":[],"relativePath":"contato.md","filePath":"contato.md"}'),s={name:"contato.md"};function l(i,e,n,d,p,c){return a(),r("div",null,e[0]||(e[0]=[t('<h1 id="contato" tabindex="-1">Contato <a class="header-anchor" href="#contato" aria-label="Permalink to &quot;Contato&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Canal</th><th>Para quê</th></tr></thead><tbody><tr><td>E-mail: <a href="mailto:fellippe@eploc.com.br" target="_blank" rel="noreferrer">fellippe@eploc.com.br</a></td><td>Tribunais, pedidos sobre privacidade e assuntos institucionais.</td></tr><tr><td><a href="https://eploc.com.br/reportar-problema.html" target="_blank" rel="noreferrer">Fale com o eploc</a></td><td>Relatar um problema, sugerir uma melhoria ou tirar uma dúvida, pelo formulário do site.</td></tr><tr><td><a href="https://chat.whatsapp.com/KW8aEPxUKRK3kcJ5yKpCju" target="_blank" rel="noreferrer">Grupo de suporte no WhatsApp</a></td><td>Dúvidas rápidas e novidades.</td></tr><tr><td><a href="https://eploc.com.br/" target="_blank" rel="noreferrer">eploc.com.br</a></td><td>Site, vídeos e novidades.</td></tr><tr><td>Instagram <a href="https://www.instagram.com/eploc.extensao" target="_blank" rel="noreferrer">@eploc.extensao</a> e TikTok <a href="https://www.tiktok.com/@eploc.extensao" target="_blank" rel="noreferrer">@eploc.extensao</a></td><td>Vídeos curtos e novidades.</td></tr></tbody></table><h2 id="erros-nos-sistemas-do-tribunal" tabindex="-1">Erros nos sistemas do tribunal <a class="header-anchor" href="#erros-nos-sistemas-do-tribunal" aria-label="Permalink to &quot;Erros nos sistemas do tribunal&quot;">​</a></h2><p>Antes de abrir um chamado no suporte do tribunal sobre uma falha no eproc, no SEI ou no RUPE:</p><ol><li>Desative o eploc pelo interruptor geral do <a href="./geral/popup">popup</a> (&quot;Extensão desativada&quot;).</li><li>Recarregue a página e tente de novo.</li><li>Se o problema continuar com o eploc desativado, ele é do sistema: abra o chamado normalmente. Se o problema sumir, ele tem relação com o eploc: fale com o desenvolvedor (pelos canais acima), e não com o suporte do tribunal.</li></ol><p>O suporte dos tribunais cuida dos sistemas oficiais, não do eploc. Dúvidas e problemas da extensão são atendidos pelo <a href="https://eploc.com.br/reportar-problema.html" target="_blank" rel="noreferrer">formulário do site</a>, pelo grupo no WhatsApp ou por e-mail.</p><p>Se precisar enviar capturas de tela ao suporte do tribunal, prefira tirá-las com o eploc desativado. Assim a tela aparece exatamente como o suporte a conhece, o que facilita o atendimento.</p><h2 id="ao-relatar-um-problema" tabindex="-1">Ao relatar um problema <a class="header-anchor" href="#ao-relatar-um-problema" aria-label="Permalink to &quot;Ao relatar um problema&quot;">​</a></h2><p>Para agilizar a resposta, informe:</p><ol><li>o tribunal e o sistema (por exemplo, eproc do TJMG, 1º grau);</li><li>a tela em que aconteceu;</li><li>o nome da funcionalidade, como aparece nas configurações;</li><li>o que você esperava e o que aconteceu;</li><li>a versão do eploc (aba <strong>Sobre</strong> das configurações) e o navegador.</li></ol><div class="warning custom-block"><p class="custom-block-title">Não envie dados reais</p><p>Não envie números de processos sigilosos, nomes de partes, CPFs ou capturas de tela com dados pessoais. Se uma imagem for necessária, cubra esses dados antes de enviar.</p></div><h2 id="desenvolvedor" tabindex="-1">Desenvolvedor <a class="header-anchor" href="#desenvolvedor" aria-label="Permalink to &quot;Desenvolvedor&quot;">​</a></h2><p>O eploc é desenvolvido e mantido por Fellippe Heitor. Programa de computador registrado no INPI sob o nº BR 51 2026 008457 1.</p>',13)]))}const b=o(s,[["render",l]]);export{u as __pageData,b as default};
